import { Link, useLocation } from "react-router-dom";
import { usePanier } from "../../hooks/usePanier";
import { useAuth } from "../../hooks/useAuth";

const navItems = [
  { path: "/",             label: "Accueil",       icon: "⊞" },
  { path: "/catalogue",   label: "Catalogue",     icon: "🔍" },
  { path: "/panier",      label: "Panier",        icon: "🛒", badge: true },
  { path: "/mes-commandes", label: "Mes commandes", icon: "📄" },
  { path: "/profil",      label: "Profil",        icon: "👤" },
];

export default function BarreNavigation() {
  const { totalArticles } = usePanier();
  const { utilisateur, deconnecter } = useAuth();
  const location = useLocation();

  return (
    <aside style={{
      width: "220px",
      background: "white",
      borderRight: "0.5px solid #e9ecef",
      height: "100vh",
      position: "fixed",
      top: 0,
      left: 0,
      display: "flex",
      flexDirection: "column",
      zIndex: 100,
    }}>
      {/* Logo */}
      <div style={{ padding: "20px", borderBottom: "0.5px solid #e9ecef" }}>
        <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
          <div style={{ width: "32px", height: "32px", background: "#3B5BDB", borderRadius: "8px", display: "flex", alignItems: "center", justifyContent: "center", color: "white", fontSize: "16px" }}>
            🛍️
          </div>
          <span style={{ fontSize: "18px", fontWeight: 700, color: "#3B5BDB" }}>E-Store</span>
        </div>
      </div>

      {/* Navigation */}
      <nav style={{ flex: 1, padding: "12px 0" }}>
        {navItems.map((item) => {
          const actif = location.pathname === item.path;
          return (
            <Link key={item.path} to={item.path} style={{
              display: "flex",
              alignItems: "center",
              gap: "10px",
              padding: "10px 20px",
              fontSize: "14px",
              fontWeight: actif ? 600 : 400,
              color: actif ? "#3B5BDB" : "#495057",
              background: actif ? "#EEF2FF" : "transparent",
              borderLeft: actif ? "3px solid #3B5BDB" : "3px solid transparent",
              transition: "all 0.15s",
            }}>
              <span style={{ fontSize: "16px" }}>{item.icon}</span>
              {item.label}
              {item.badge && totalArticles > 0 && (
                <span style={{ marginLeft: "auto", background: "#E03131", color: "white", fontSize: "11px", fontWeight: 700, padding: "1px 7px", borderRadius: "10px" }}>
                  {totalArticles}
                </span>
              )}
            </Link>
          );
        })}
      </nav>

      {/* Déconnexion */}
      <div style={{ borderTop: "0.5px solid #e9ecef", padding: "12px 0" }}>
        {utilisateur ? (
          <button onClick={deconnecter} style={{
            display: "flex", alignItems: "center", gap: "10px",
            padding: "10px 20px", width: "100%", background: "none",
            border: "none", cursor: "pointer", fontSize: "14px", color: "#E03131",
          }}>
            <span>🚪</span> Se déconnecter
          </button>
        ) : (
          <Link to="/connexion" style={{ display: "flex", alignItems: "center", gap: "10px", padding: "10px 20px", fontSize: "14px", color: "#3B5BDB" }}>
            <span>🔑</span> Se connecter
          </Link>
        )}
      </div>
    </aside>
  );
}
